#!/usr/bin/env python3
"""Apply the GPU-first patch to the pinned upstream revision; reject unexpected code."""
import json
from pathlib import Path
import sys
root = Path(sys.argv[1])
changes = json.loads("{\"src/gozen_video.hpp\":[[\"\\t// Private functions.\\n\",\"\\t// Private functions.\\n\\tint open_internal(const String& video_path, int hw_mode);\\n\\tbool hw_attempted = false;\\n\"]],\"src/gozen_video.cpp\":[[\"int GoZenVideo::open(const String& video_path) {\",\"#include <cstdlib>\\n#include <cstring>\\n\\n#ifdef _WIN32\\nstatic AVPixelFormat gozen_gpu_format(AVCodecContext *ctx, const AVPixelFormat *formats) {\\n    const AVHWDeviceContext *device = ctx->hw_device_ctx ?\\n        reinterpret_cast<const AVHWDeviceContext *>(ctx->hw_device_ctx->data) : nullptr;\\n    const AVPixelFormat wanted = device && device->type == AV_HWDEVICE_TYPE_D3D11VA ?\\n        AV_PIX_FMT_D3D11 : AV_PIX_FMT_DXVA2_VLD;\\n    for (const AVPixelFormat *p = formats; *p != AV_PIX_FMT_NONE; ++p)\\n        if (*p == wanted) return *p;\\n    // FFmpeg may offer only software formats for unsupported profiles.\\n    for (const AVPixelFormat *p = formats; *p != AV_PIX_FMT_NONE; ++p) {\\n        const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(*p);\\n        if (desc && !(desc->flags & AV_PIX_FMT_FLAG_HWACCEL)) return *p;\\n    }\\n    return AV_PIX_FMT_NONE;\\n}\\n#endif\\n\\nint GoZenVideo::open(const String& video_path) {\\n    if (loaded) return open_internal(video_path, 0);\\n#ifdef _WIN32\\n    const char *mode = std::getenv(\\\"GOZEN_HWDEC\\\");\\n    int attempts[] = {1, 2, 0};\\n    if (mode && std::strcmp(mode, \\\"0\\\") == 0) attempts[0] = attempts[1] = 0;\\n    else if (mode && std::strcmp(mode, \\\"dxva2\\\") == 0) attempts[0] = 2, attempts[1] = 0;\\n    else if (mode && std::strcmp(mode, \\\"d3d11va\\\") == 0) attempts[1] = 0;\\n    for (int hw_mode : attempts) {\\n        hw_attempted = false;\\n        int result = open_internal(video_path, hw_mode);\\n        if (loaded || !hw_attempted || hw_mode == 0) return result;\\n        close();\\n        UtilityFunctions::print(\\\"GoZen GPU: hardware open failed; trying fallback\\\");\\n    }\\n#endif\\n    return open_internal(video_path, 0);\\n}\\n\\nint GoZenVideo::open_internal(const String& video_path, int hw_mode) {\"],[\"\\tFFmpeg::enable_multithreading(av_codec_ctx.get(), av_codec);\\n\\n\\t// Open codec - Video.\",\"    FFmpeg::enable_multithreading(av_codec_ctx.get(), av_codec);\\n#ifdef _WIN32\\n    // GM107 supports H.264 8-bit 4:2:0, not general HEVC/AV1 decoding.\\n    if (hw_mode && av_stream->codecpar->codec_id == AV_CODEC_ID_H264) {\\n        hw_attempted = true;\\n        const AVHWDeviceType type = hw_mode == 1 ? AV_HWDEVICE_TYPE_D3D11VA : AV_HWDEVICE_TYPE_DXVA2;\\n        const AVPixelFormat wanted = hw_mode == 1 ? AV_PIX_FMT_D3D11 : AV_PIX_FMT_DXVA2_VLD;\\n        bool supported = false;\\n        for (int i = 0; const AVCodecHWConfig *cfg = avcodec_get_hw_config(av_codec, i); ++i) {\\n            if ((cfg->methods & AV_CODEC_HW_CONFIG_METHOD_HW_DEVICE_CTX) &&\\n                cfg->device_type == type && cfg->pix_fmt == wanted) {\\n                supported = true;\\n                break;\\n            }\\n        }\\n        if (!supported || av_hwdevice_ctx_create(&av_codec_ctx->hw_device_ctx, type, nullptr, nullptr, 0) < 0) {\\n            close();\\n            return ERR_UNAVAILABLE;\\n        }\\n        av_codec_ctx->get_format = gozen_gpu_format;\\n        av_codec_ctx->thread_count = 1;\\n        av_codec_ctx->thread_type = 0;\\n    }\\n#endif\\n    bool hw_confirmed = false;\\n\\n\\t// Open codec - Video.\"],[\"\\t\\tresponse = FFmpeg::get_frame(av_format_ctx.get(), av_codec_ctx.get(), av_stream->index, av_frame.get(),\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t av_packet.get());\",\"\\t\\tresponse = FFmpeg::get_frame(av_format_ctx.get(), av_codec_ctx.get(), av_stream->index, av_frame.get(),\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t av_packet.get(), &hw_confirmed);\"],[\"\\t// Checking for interlacing and what type of interlacing.\",\"    if (hw_confirmed) {\\n        UtilityFunctions::print(hw_mode == 1 ? \\\"GoZen GPU: D3D11VA decoded first frame\\\" : \\\"GoZen GPU: DXVA2 decoded first frame\\\");\\n    } else {\\n        UtilityFunctions::print(\\\"GoZen GPU: software decoding\\\");\\n    }\\n\\n\\t// Checking for interlacing and what type of interlacing.\"],[\"av_frame->format == AV_PIX_FMT_YUVA420P);\",\"av_frame->format == AV_PIX_FMT_YUVA420P || av_frame->format == AV_PIX_FMT_NV12);\"],[\"\\tif (using_sws) {\\n\\t\\tsws_scale_frame(sws_ctx.get(), av_sws_frame.get(), av_frame.get());\",\"    // Preserve the existing three R8 textures and shaders; no PCK changes.\\n    // Directly split NV12 UV into the original planar interface.\\n    if (av_frame->format == AV_PIX_FMT_NV12) {\\n        uint8_t *y = y_data->ptrw();\\n        uint8_t *u = u_data->ptrw();\\n        uint8_t *v = v_data->ptrw();\\n        for (int i = 0; i < actual_resolution.y; ++i)\\n            memcpy(y + i * actual_resolution.x, av_frame->data[0] + i * av_frame->linesize[0], actual_resolution.x);\\n        for (int i = 0; i < uv_height; ++i) {\\n            const uint8_t *uv = av_frame->data[1] + i * av_frame->linesize[1];\\n            for (int j = 0; j < uv_width; ++j) {\\n                u[i * uv_width + j] = uv[2 * j];\\n                v[i * uv_width + j] = uv[2 * j + 1];\\n            }\\n        }\\n        return;\\n    }\\n\\n\\tif (using_sws) {\\n\\t\\tsws_scale_frame(sws_ctx.get(), av_sws_frame.get(), av_frame.get());\"],[\"\\tFFmpeg::get_frame(av_format_ctx.get(), av_codec_ctx.get(), av_stream->index, av_frame.get(), av_packet.get());\\n\\n\\tif (!skip)\",\"\\tif (FFmpeg::get_frame(av_format_ctx.get(), av_codec_ctx.get(), av_stream->index, av_frame.get(), av_packet.get()) < 0) return false;\\n\\n\\tif (!skip)\"],[\"\\t\\t\\t} else if (response == AVERROR_EOF) {\\n\\t\\t\\t\\t_log_err(\\\"End of file reached! Going back 1 frame!\\\");\",\"\\t\\t\\t} else if (response == AVERROR_EOF) {\\n\\t\\t\\t\\tif (++attempts > 10 || frame_nr <= 0) return ERR_FILE_EOF;\\n\\t\\t\\t\\t_log_err(\\\"End of file reached! Going back 1 frame!\\\");\"]],\"src/ffmpeg.hpp\":[[\"AVPacket* packet);\",\"AVPacket* packet, bool* hw_used = nullptr);\"]],\"src/ffmpeg.cpp\":[[\"AVPacket* packet) {\\n\\tint response = 0;\",\"AVPacket* packet, bool* hw_used) {\\n\\tint response = 0;\"],[\"\\treturn response;\\n}\\n\\nenum AVPixelFormat FFmpeg::get_hw_format\",\"    if (response == 0 && frame->hw_frames_ctx) {\\n        AVFrame *download = av_frame_alloc();\\n        if (!download) return AVERROR(ENOMEM);\\n        response = av_hwframe_transfer_data(download, frame, 0);\\n        if (response >= 0) response = av_frame_copy_props(download, frame);\\n        if (response >= 0) {\\n            av_frame_unref(frame);\\n            av_frame_move_ref(frame, download);\\n            if (hw_used) *hw_used = true;\\n        }\\n        av_frame_free(&download);\\n    }\\n\\treturn response;\\n}\\n\\nenum AVPixelFormat FFmpeg::get_hw_format\"]],\"SConstruct\":[[\"    env.Append(LINKFLAGS=[\\\"-static\\\"], LIBS=LIBS_COMMON)\",\"    env.Append(CCFLAGS=[\\\"-march=x86-64\\\", \\\"-mtune=generic\\\"], LINKFLAGS=[\\\"-static\\\"], LIBS=LIBS_COMMON)\"],[\"LIBS=[\\\"ws2_32\\\", \\\"bcrypt\\\", \\\"secur32\\\", \\\"shlwapi\\\", \\\"mfuuid\\\", \\\"strmiids\\\"],\",\"LIBS=[\\\"ws2_32\\\", \\\"bcrypt\\\", \\\"secur32\\\", \\\"shlwapi\\\", \\\"mfuuid\\\", \\\"strmiids\\\", \\\"ole32\\\", \\\"user32\\\", \\\"uuid\\\"],\"]],\"build.py\":[[\"    \\\"--disable-hwaccels\\\",\",\"    # GPU edition: select Windows hardware accelerators in the Windows build.\"],[\"        \\\"--extra-cflags=-fPIC\\\",\\n        \\\"--enable-libvpx\\\",\\n        \\\"--enable-schannel\\\",\",\"        \\\"--extra-cflags=-fPIC -march=x86-64 -mtune=generic\\\",\\n        \\\"--enable-libvpx\\\",\\n        \\\"--enable-schannel\\\",\\n        \\\"--enable-d3d11va\\\",\\n        \\\"--enable-dxva2\\\",\\n        \\\"--enable-hwaccel=h264_d3d11va2,h264_dxva2\\\",\"],[\"    print(\\\"Compiling FFmpeg for Windows ...\\\")\",\"    from pathlib import Path\\n    config = Path(\\\"ffmpeg/config_components.h\\\").read_text()\\n    for flag in (\\\"CONFIG_H264_D3D11VA2_HWACCEL\\\", \\\"CONFIG_H264_DXVA2_HWACCEL\\\"):\\n        if f\\\"#define {flag} 1\\\" not in config:\\n            raise RuntimeError(f\\\"Required acceleration missing: {flag}\\\")\\n    print(\\\"Preflight: both H.264 Windows hardware accelerators enabled\\\")\\n    print(\\\"Compiling FFmpeg for Windows ...\\\")\"]]}")
for rel, edits in changes.items():
    p = root / rel
    s = p.read_text(encoding="utf-8")
    for old, new in edits:
        count = s.count(old)
        if count != 1:
            raise RuntimeError(f"{rel}: expected one patch anchor, found {count}: {old[:100]}")
        s = s.replace(old, new, 1)
    p.write_text(s, encoding="utf-8")
    print("Patched", rel)
